# --- jiko_bridge_houdini.jb_plugin ---

# The discovery SOP: run the asset importer and publish the graph.


def discover_assets(sop: hou.SopNode, owner: hou.OpNode) -> None:
    """Expose the imported asset graph as JSON on the OUT_GRAPH detail geometry."""
    geometry = node_geometry(sop)
    add_string_attribs(geometry, hou.attribType.Prim, ('asset_id', 'source', 'name'))
    graph: dict[str, Any] = {'version': 1, 'roots': [], 'assets': [], 'warnings': []}
    asset = cached_asset(owner)
    if owner.evalParm('cached'):
        graph['mode'] = 'cached'
        graph['cache_root'] = owner.evalParm('cache_path')
        graph['asset'] = {
            'vault_name': asset.vault_name,
            'pack_name': asset.pack_name,
            'asset_name': asset.asset_name,
        }
    elif asset.files:
        importer = JbAssetImporter(owner)
        with hou.InterruptableOperation('Import Jiko Bridge assets'):
            graph = importer.build_graph(geometry)
        plan_instances(graph)
    set_global_attrib(geometry, 'jiko_graph', json.dumps(graph, ensure_ascii=False))
    if graph['warnings']:
        raise hou.NodeWarning('\n'.join(graph['warnings'][:20]))


def active_asset(node: hou.OpNode) -> None:
    """HDA Active button callback."""
    JbCommands(node).active_asset()


def import_asset(node: hou.OpNode) -> None:
    """HDA Import button callback."""
    JbCommands(node).import_asset()


# --- jiko_bridge_houdini.scene.jb_scene_layer_plan ---

# Map discovered models to USD prims and cache files without writing to disk.

CACHE_ROOT_PRIM = 'Asset'
GEOMETRY_PRIM = 'geometry'


def cache_file(cache_root: str, metadata: dict[str, Any]) -> str:
    """Cache path of one asset, validated against invalid name characters."""
    if not cache_root:
        raise hou.NodeError('Set Cache Path before assembling USD layers.')
    names = []
    for key in ('vaultName', 'packName', 'assetName'):
        value = metadata.get(key, '')
        if not value or value in ('.', '..') or re.search('[<>:"/\\\\|?*\\x00-\\x1f]', value):
            raise hou.NodeError(f'Invalid or missing {key} for the cache path: {value!r}')
        if value.endswith(('.', ' ')):
            raise hou.NodeError(f'Invalid {key} for the cache path: {value!r}')
        names.append(value)
    return os.path.join(cache_root, *names, names[-1] + '.usd').replace('\\', '/')


def prim_name(source: str) -> str:
    """Stable prim name of one source file inside an asset container."""
    source = os.path.normcase(os.path.normpath(source))
    return f"{_base_name(source)}_{hashlib.sha1(source.encode('utf-8')).hexdigest()[:10]}"


def _base_name(source: str) -> str:
    return Tf.MakeValidIdentifier(os.path.splitext(os.path.basename(source))[0])


def model_prim_path(source: str) -> str:
    """Where one file's geometry lives inside its asset container."""
    return f'/{CACHE_ROOT_PRIM}/{GEOMETRY_PRIM}/{prim_name(source)}'


def prototype_path(record: dict[str, Any]) -> str:
    """Prototype holding a USD-sourced asset in the layer that references it."""
    sources = '|'.join((entry['source'] for entry in record['files']))
    digest = hashlib.sha1(sources.encode('utf-8')).hexdigest()[:10]
    name = str(record['asset'].get('assetName') or record['id'])
    return f'/__JikoPrototypes/{Tf.MakeValidIdentifier(name)}_{digest}'


def asset_entry(cache_root: str, record: dict[str, Any]) -> dict[str, Any] | None:
    """Asset entry of one record, or None when the record holds no models."""
    models: list[dict] = []
    for entry in record['models']:
        converted = entry['format'] in CONVERTED_EXTENSIONS
        models.append(
            {
                'id': entry['id'],
                'record': record,
                'source': entry['source'],
                'format': entry['format'],
                'converted': converted,
                'file': (
                    cache_file(cache_root, record['asset'])
                    if converted
                    else os.path.abspath(entry['source']).replace('\\', '/')
                ),
                'prim': model_prim_path(entry['source']),
            }
        )
    if not models:
        return None
    formats = {model['converted'] for model in models}
    if len(formats) > 1:
        raise hou.NodeError(
            'An asset mixes converted and USD model files: '
            + ', '.join((model['source'] for model in models))
        )
    return {
        'id': record['id'],
        'record': record,
        'converted': formats.pop(),
        'root': f'/{CACHE_ROOT_PRIM}',
        'prototype': prototype_path(record),
        'models': models,
    }


def layer_plan(owner: hou.OpNode, graph: dict[str, Any]) -> dict[str, Any]:
    """Turn the asset graph into cache layers and one container per asset."""
    cache_root = absolute_path(str(owner.evalParm('cache_path')))
    if graph.get('mode') == 'cached':
        metadata = {
            'vaultName': owner.evalParm('vault_name'),
            'packName': owner.evalParm('pack_name'),
            'assetName': owner.evalParm('asset_name'),
        }
        path = cache_file(cache_root, metadata)
        if not os.path.isfile(path):
            raise hou.NodeError(f'Cached USD does not exist: {path}')
        return {'mode': 'cached', 'path': path, 'assets': {}, 'layers': []}
    assets: dict[str, dict] = {}
    layers: dict[str, dict] = {}
    identities: dict[str, tuple] = {}
    for record in graph['assets']:
        asset = asset_entry(cache_root, record)
        if asset is None:
            continue
        assets[record['id']] = asset
        if not asset['converted']:
            continue
        path = asset['models'][0]['file']
        key = os.path.normcase(os.path.abspath(path))
        identity = tuple(
            (record['asset'].get(name) for name in ('vaultName', 'packName', 'assetName'))
        )
        if key in identities and identities[key] != identity:
            raise hou.NodeError(f'Different assets resolve to the same cache file: {path}')
        identities[key] = identity
        layer = layers.setdefault(
            key,
            {
                'path': path,
                'reuse': os.path.isfile(path) and (not owner.evalParm('override')),
                'asset_id': record['id'],
                'record': record,
                'models': [],
            },
        )
        layer['models'].extend(asset['models'])
    sources = {
        os.path.normcase(os.path.abspath(model['file']))
        for asset in assets.values()
        for model in asset['models']
        if not model['converted']
    }
    if sources.intersection(layers):
        raise hou.NodeError(
            'A cache destination matches an original USD source. Choose a separate Cache Path.'
        )
    return {'mode': 'build', 'assets': assets, 'layers': list(layers.values())}


# --- jiko_bridge_houdini.scene.jb_scene_cache ---

# Save the assembled stage through the single USD ROP inside this HDA.


def _cache_root(owner: hou.OpNode) -> str:
    path = absolute_path(str(owner.evalParm('cache_path')))
    if not path:
        raise hou.Error('Set Cache Path before saving USD.')
    return path


def scene_output_path(owner: hou.OpNode) -> str:
    """Path of the assembled scene USD for the selected asset."""
    if not owner.evalParm('asset_name'):
        return ''
    metadata = {
        'vaultName': owner.evalParm('vault_name'),
        'packName': owner.evalParm('pack_name'),
        'assetName': owner.evalParm('asset_name'),
    }
    asset_path = cache_file(_cache_root(owner), metadata)
    return os.path.splitext(asset_path)[0] + '.scene.usd'


def cache_save_pattern(owner: hou.OpNode) -> str:
    """Glob pattern matching every cached asset file."""
    return '"' + _cache_root(owner).rstrip('/') + '/*"'


def _path_key(path: str) -> str:
    return os.path.normcase(os.path.abspath(hou.text.expandString(path)))


def _inside_cache(path: str, root: str) -> bool:
    try:
        return os.path.commonpath((_path_key(path), _path_key(root))) == _path_key(root)
    except ValueError:
        return False


def save_usd(owner: hou.OpNode) -> str:
    """Assemble the stage and write it through the HDA's USD ROP."""
    output = scene_output_path(owner)
    if not output or (not owner.evalParm('cached') and (not cached_asset(owner).files)):
        raise hou.Error('Select an asset before saving USD.')
    root = _cache_root(owner)
    override = bool(owner.evalParm('override'))
    if os.path.isfile(output) and (not override):
        raise hou.Error(f'Scene already exists. Enable Override to overwrite it:\n{output}')
    assembly = cast(hou.LopNode, owner.node('assemble_usd'))
    rop = owner.node('usd_rop')
    if assembly is None or rop is None:
        raise hou.Error('Rebuild the HDA to add the USD assembly and USD ROP nodes.')
    assembly.cook(force=True)
    stage = assembly.stage()
    if stage is None or assembly.errors():
        raise hou.Error('USD assembly failed:\n' + '\n'.join(assembly.errors()))
    if not stage.GetPrimAtPath('/World'):
        raise hou.Error('The assembled stage has no /World primitive to save.')
    paths = {_path_key(output): output}
    for layer in stage.GetUsedLayers():
        if layer.realPath and _path_key(layer.realPath) == _path_key(output):
            raise hou.Error(f'The scene output is also a referenced source file:\n{output}')
        info = layer.GetPrimAtPath('/HoudiniLayerInfo')
        path = info.customData.get('HoudiniSavePath') if info else None
        if not path:
            continue
        path = hou.text.expandString(path)
        if not _inside_cache(path, root):
            continue
        if _path_key(path) == _path_key(output):
            raise hou.Error(f'Scene output collides with an asset layer:\n{output}')
        if os.path.isfile(path) and (not override):
            raise hou.Error(
                f'A writable cache layer already exists. Import or enable Override:\n{path}'
            )
        paths[_path_key(path)] = path
    for path in paths.values():
        os.makedirs(os.path.dirname(path), exist_ok=True)
    cast(hou.Parm, rop.parm('execute')).pressButton()
    if rop.errors():
        raise hou.Error('USD save failed:\n' + '\n'.join(rop.errors()))
    missing = [path for path in paths.values() if not os.path.isfile(path)]
    if missing:
        raise hou.Error('USD ROP did not write these files:\n' + '\n'.join(missing))
    get_logger('jiko_bridge_houdini.scene.jb_scene_cache').info('Saved USD scene: %s', output)
    return output


# --- jiko_bridge_houdini.scene.jb_scene_usd ---

# Author cache layers and USD instances during cook, without disk writes.


def _layer_metrics(layer: Sdf.Layer) -> None:
    stage = Usd.Stage.Open(layer)
    UsdGeom.SetStageUpAxis(stage, UsdGeom.Tokens.y)
    UsdGeom.SetStageMetersPerUnit(stage, 1.0)
    layer.framesPerSecond = hou.fps()
    layer.timeCodesPerSecond = hou.fps()


def _set_instance_transform(prim: Usd.Prim, values: Sequence[float]) -> None:
    matrix = Gf.Matrix4d(*values)
    xform = UsdGeom.Xformable(prim)
    xform.MakeMatrixXform().Set(matrix)


def _copy_geometry_roots(source: Sdf.Layer, destination: Sdf.Layer, parent: str) -> None:
    roots = [prim for prim in source.rootPrims if prim.name != 'HoudiniLayerInfo']
    mapping = [(prim.path, Sdf.Path(parent).AppendChild(prim.name)) for prim in roots]
    for old, new in mapping:
        if not Sdf.CopySpec(source, old, destination, new):
            raise hou.NodeError(f'Cannot copy imported USD geometry: {old}')

    def remap(path: Sdf.Path) -> Sdf.Path:
        if path.HasPrefix(Sdf.Path(parent)):
            return path
        for old, new in mapping:
            if path.HasPrefix(old):
                return path.ReplacePrefix(old, new)
        return path

    def fix_links(path: Sdf.Path) -> None:
        spec = destination.GetObjectAtPath(path)
        if spec is None:
            return
        for field in ('targetPaths', 'connectionPaths', 'inheritPaths', 'specializes'):
            if spec.HasInfo(field):
                values = spec.GetInfo(field)
                spec.SetInfo(
                    field,
                    Sdf.PathListOp.CreateExplicit(
                        [remap(value) for value in values.GetAppliedItems()]
                    ),
                )
        if spec.HasInfo('references'):
            values = spec.GetInfo('references').GetAppliedItems()
            spec.SetInfo(
                'references',
                Sdf.ReferenceListOp.CreateExplicit(
                    [
                        (
                            Sdf.Reference(
                                value.assetPath,
                                remap(value.primPath),
                                value.layerOffset,
                                value.customData,
                            )
                            if not value.assetPath
                            else value
                        )
                        for value in values
                    ]
                ),
            )

    paths: list[Sdf.Path] = []
    destination.Traverse(Sdf.Path(parent), lambda path: paths.append(Sdf.Path(str(path))))
    for path in paths:
        fix_links(path)


class LayerAssembly:

    def __init__(self, node: hou.LopNode, plan: dict[str, Any], geometry: hou.Geometry) -> None:
        self.node = node
        self.plan = plan
        self.geometry = geometry
        self.layers: dict[str, Sdf.Layer] = {}
        self.stages: dict[str, Usd.Stage] = {}
        self.asset_layers: dict[str, str] = {}
        self.usd_sources: dict[str, Usd.Stage] = {}

    def allocate(self) -> None:
        """Allocate every target before creating references to it."""
        for item in self.plan['layers']:
            if item['reuse']:
                stage = Usd.Stage.Open(item['path'])
                if stage is None:
                    raise hou.NodeError(f"Cannot read cached USD: {item['path']}")
                for model in item['models']:
                    if not stage.GetPrimAtPath(model['prim']):
                        raise hou.NodeError(
                            f"Cache schema differs for {item['path']}; rebuild with Override."
                        )
                self.asset_layers[item['asset_id']] = item['path']
                continue
            layer = loputils.createPythonLayer(self.node, item['path'])
            _layer_metrics(layer)
            layer.defaultPrim = CACHE_ROOT_PRIM
            stage = Usd.Stage.Open(layer)
            if stage is None:
                raise hou.NodeError(f"Cannot create cache layer: {item['path']}")
            container = f'/{CACHE_ROOT_PRIM}'
            UsdGeom.Xform.Define(stage, container)
            UsdGeom.Xform.Define(stage, f'{container}/{GEOMETRY_PRIM}')
            for model in item['models']:
                UsdGeom.Xform.Define(stage, model['prim'])
            self.asset_layers[item['asset_id']] = layer.identifier
            self.layers[item['path']] = layer
            self.stages[item['path']] = stage

    def copy_geometry(self, stage: Usd.Stage, model: dict[str, Any]) -> None:
        """Convert one prepared model to USD and copy it into the cache layer."""
        primitive = next(
            (
                prim
                for prim in self.geometry.prims()
                if prim.stringAttribValue('asset_id') == model['id']
            ),
            None,
        )
        if primitive is None:
            raise hou.NodeError(f"Prepared geometry is missing for {model['source']}")
        geometry = unpack_piece(self.geometry, primitive, convert_polysoup=False)
        if not geometry.prims() and (not geometry.points()):
            return
        identifier = self.node.addLockedGeometry(model['id'], geometry)
        imported = Usd.Stage.Open(identifier)
        if imported is None:
            raise hou.NodeError(f"Cannot convert geometry to USD: {model['source']}")
        imported.SetEditTarget(imported.GetSessionLayer())
        while True:
            instances = [prim for prim in imported.Traverse() if prim.IsInstance()]
            if not instances:
                break
            for prim in instances:
                prim.SetInstanceable(False)
        flattened = imported.Flatten()
        parent = model['prim'] + '/geometry'
        UsdGeom.Xform.Define(stage, parent)
        destination = stage.GetRootLayer()
        _copy_geometry_roots(flattened, destination, parent)

    def usd_source(self, path: str) -> Usd.Stage:
        """Open a USD source file once and reuse the stage."""
        if path not in self.usd_sources:
            stage = Usd.Stage.Open(path)
            if stage is None:
                raise hou.NodeError(f'Cannot open USD source: {path}')
            self.usd_sources[path] = stage
        return self.usd_sources[path]

    def reference(
        self, stage: Usd.Stage, path: str, identifier: str, ancestors: tuple[str, ...] = ()
    ) -> Usd.Prim:
        """One reference per asset, however many files the asset holds."""
        if identifier in ancestors:
            raise hou.NodeError(f'Cyclic USD reference at {path}')
        asset = self.plan['assets'][identifier]
        prim = UsdGeom.Xform.Define(stage, path).GetPrim()
        if asset['converted']:
            target = self.asset_layers[identifier]
            if target == stage.GetRootLayer().identifier:
                prim.GetReferences().AddInternalReference(asset['root'])
            else:
                prim.GetReferences().AddReference(target, asset['root'])
        else:
            prototype = asset['prototype']
            if not stage.GetRootLayer().GetPrimAtPath(prototype):
                stage.CreateClassPrim('/__JikoPrototypes')
                stage.CreateClassPrim(prototype).SetTypeName('Xform')
                self.author_usd_source(stage, prototype, asset, ancestors + (identifier,))
            prim.GetReferences().AddInternalReference(prototype)
        prim.SetInstanceable(True)
        return prim

    def author_usd_source(
        self, stage: Usd.Stage, path: str, asset: dict[str, Any], ancestors: tuple[str, ...]
    ) -> None:
        """Keep original USD on disk; author replacements as stronger opinions."""
        geometry = f'{path}/{GEOMETRY_PRIM}'
        UsdGeom.Xform.Define(stage, geometry)
        for model in asset['models']:
            original = self.usd_source(model['file'])
            source_path = geometry + '/' + Sdf.Path(model['prim']).name
            UsdGeom.Xform.Define(stage, source_path)
            for root in original.GetPseudoRoot().GetChildren():
                if root.GetName() == 'HoudiniLayerInfo':
                    continue
                prim = stage.DefinePrim(source_path + '/' + root.GetName())
                prim.GetReferences().AddReference(model['file'], root.GetPath())
            for location in asset['record']['remove_objects']:
                target = Sdf.Path(source_path + location)
                for prefix in target.GetPrefixes():
                    prim = stage.GetPrimAtPath(prefix)
                    if prim and prim.IsInstance():
                        prim.SetInstanceable(False)
                stage.OverridePrim(target).SetActive(False)
        self.instances(stage, path, asset['record'], ancestors)

    def instances(
        self, stage: Usd.Stage, parent: str, record: dict[str, Any], ancestors: tuple[str, ...] = ()
    ) -> None:
        """Author one instanced reference per replaced placeholder."""
        for index, instance in enumerate(record['instances']):
            if not instance.get('replace'):
                continue
            container = parent + '/instances'
            UsdGeom.Xform.Define(stage, container)
            path = f'{container}/instance_{index:04d}'
            prim = self.reference(stage, path, instance['target'], ancestors)
            _set_instance_transform(prim, instance['transform'])

    def author(self) -> None:
        """Fill every newly created cache layer with geometry and instances."""
        self.allocate()
        for item in self.plan['layers']:
            if item['reuse']:
                continue
            stage = self.stages[item['path']]
            for model in item['models']:
                self.copy_geometry(stage, model)
            asset = self.plan['assets'][item['asset_id']]
            self.instances(stage, asset['root'], item['record'], (item['asset_id'],))


def assemble_usd(node: hou.LopNode) -> None:
    """Python LOP entry point: assemble the whole stage on cook."""
    owner = cast(hou.OpNode, node.parent())
    graph: dict[str, Any] = {'mode': 'cached'}
    geometry = None
    if not owner.evalParm('cached'):
        source = cast(hou.SopNode, owner.node('geometry/OUT_GEOMETRY'))
        geometry = source.geometry()
        graph = json.loads(str(cast(hou.Geometry, geometry).attribValue('jiko_graph')))
    plan = layer_plan(owner, graph)
    node.editableStage()
    if plan['mode'] != 'cached' and (not graph['roots']):
        return
    scene = loputils.createPythonLayer(node)
    _layer_metrics(scene)
    scene.defaultPrim = 'World'
    stage = Usd.Stage.Open(scene)
    UsdGeom.Xform.Define(stage, '/World')
    root = '/World/' + Tf.MakeValidIdentifier(owner.name())
    UsdGeom.Xform.Define(stage, root)
    if plan['mode'] == 'cached':
        prim = stage.DefinePrim(root + '/asset')
        prim.GetReferences().AddReference(plan['path'])
        prim.SetInstanceable(True)
    else:
        assembly = LayerAssembly(node, plan, cast(hou.Geometry, geometry))
        assembly.author()
        for index, identifier in enumerate(graph['roots']):
            assembly.reference(stage, f'{root}/model_{index:04d}', identifier)
    node.addSubLayer(scene.identifier)


